CREATE OR REPLACE FUNCTION public.fn_spin_shortfall_funds_the_escrow()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_drawn     numeric;
  v_prize     numeric;
  v_shortfall numeric;
BEGIN
  IF NEW.kind <> 'adjustment' OR NEW.note IS NULL OR NEW.note NOT LIKE 'SHORTFALL %' THEN
    RETURN NULL;
  END IF;
  IF COALESCE(NEW.multiplier, 0) <= 0 OR COALESCE(NEW.buy_in, 0) <= 0 THEN
    RETURN NULL;
  END IF;

  SELECT -l.amount INTO v_drawn
    FROM public.spin_reserve_ledger l
   WHERE l.tournament_id = NEW.tournament_id AND l.kind = 'jackpot_draw'
   ORDER BY l.created_at ASC LIMIT 1;

  v_prize     := round(NEW.multiplier * NEW.buy_in, 2);
  v_shortfall := round(v_prize - COALESCE(v_drawn, 0), 2);
  IF v_shortfall <= 0 THEN
    RETURN NULL;
  END IF;

  PERFORM public.fn_ca_escrow_apply(
    NEW.tournament_id,
    'spin reserve shortfall covered by the operator',
    0, 0, 0, 0, v_shortfall
  );
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_spin_escrow_is_enforced()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.enforced THEN
    RETURN NEW;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.tournaments t
     WHERE t.id = NEW.tournament_id
       AND (COALESCE(t.variant, '') = 'spin' OR COALESCE(t.is_premium_spin, false))
  ) THEN
    RETURN NEW;
  END IF;
  /* A row that opens SHORT stays tracked: fn_ca_escrow_apply can open an
     escrow at first sight from the shadow of an event already in flight, and
     an event broken before the escrow saw it must not have its next payment
     refused by a guard switched on afterwards. */
  IF COALESCE(NEW.prize_balance, 0)  < -0.005
     OR COALESCE(NEW.bounty_balance, 0) < -0.005
     OR COALESCE(NEW.fee_balance, 0)    < -0.005 THEN
    RETURN NEW;
  END IF;
  NEW.enforced := true;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_ca_escrow_on_seat_transfer_leg()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.metadata->>'entry_split_version' = '2' THEN
    IF round(NEW.amount,2) IS DISTINCT FROM round((NEW.metadata->>'entry_prize')::numeric
        + (NEW.metadata->>'entry_bounty')::numeric + (NEW.metadata->>'entry_fee')::numeric,2)
       OR (NEW.metadata->>'entry_prize')::numeric < 0
       OR (NEW.metadata->>'entry_bounty')::numeric < 0
       OR (NEW.metadata->>'entry_fee')::numeric < 0 THEN
      RAISE EXCEPTION 'Satellite transfer does not match its funded split' USING ERRCODE='23514';
    END IF;
    PERFORM public.fn_ca_escrow_apply(NEW.to_entity_id, 'satellite split entry',
      p_gross_in => round(NEW.amount - (NEW.metadata->>'entry_fee')::numeric,2),
      p_bounty_in => (NEW.metadata->>'entry_bounty')::numeric);
    RETURN NULL;
  END IF;
  PERFORM public.fn_ca_escrow_apply(NEW.to_entity_id, 'satellite seat in', p_satellite_in => round(NEW.amount, 2));
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.zz_chip_ledger_key_is_claimed_once()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  /* 99.92% of legs carry no key and this does nothing for them. */
  IF NEW.idempotency_key IS NULL THEN
    RETURN NEW;
  END IF;

  /* No ON CONFLICT: the unique violation IS the refusal, and it must reach the
     caller exactly as ux_chip_ledger_idempotency_key's does today. Both are
     live until the cut; either one refusing is the correct outcome. */
  INSERT INTO public.chip_ledger_idem (idempotency_key, leg_id, created_at)
  VALUES (NEW.idempotency_key, NEW.id, COALESCE(NEW.created_at, now()));

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_ca_attested_day_is_restated()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE
  v_reason text := NULLIF(current_setting('app.ledger_maintenance', true), '');
  r record;
  v_res jsonb;
BEGIN
  IF v_reason IS NULL THEN
    RETURN NULL;
  END IF;

  IF TG_OP = 'DELETE' THEN
    FOR r IN
      SELECT DISTINCT o.created_at::date AS day
        FROM old_rows o
        JOIN public.ca_ledger_day_manifests m ON m.day = o.created_at::date
       ORDER BY 1
    LOOP
      v_res := public.fn_ca_ledger_day_manifest(r.day, 'maintenance:' || v_reason);
      IF COALESCE((v_res->>'tampered')::boolean, false) THEN
        RAISE EXCEPTION 'the manifest for % could not be restated after maintenance "%": %', r.day, v_reason, v_res
          USING ERRCODE = 'P0403';
      END IF;
    END LOOP;
  ELSE
    FOR r IN
      SELECT DISTINCT d.day
        FROM (SELECT created_at::date AS day FROM old_rows
              UNION
              SELECT created_at::date FROM new_rows) d
        JOIN public.ca_ledger_day_manifests m ON m.day = d.day
       ORDER BY 1
    LOOP
      v_res := public.fn_ca_ledger_day_manifest(r.day, 'maintenance:' || v_reason);
      IF COALESCE((v_res->>'tampered')::boolean, false) THEN
        RAISE EXCEPTION 'the manifest for % could not be restated after maintenance "%": %', r.day, v_reason, v_res
          USING ERRCODE = 'P0403';
      END IF;
    END LOOP;
  END IF;

  RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.fn_attach_bounty_award_obligation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_context text := current_setting('app.bounty_obligation_id',true);
  v_obligation_id uuid;
  v_activation_generation bigint;
BEGIN
  IF NEW.bounty_obligation_id IS NULL THEN
    IF COALESCE(v_context,'')
         ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' THEN
      v_obligation_id := v_context::uuid;
      SELECT o.id,o.activation_generation
        INTO NEW.bounty_obligation_id,v_activation_generation
        FROM public.tournament_bounty_obligations o
       WHERE o.id=v_obligation_id AND o.tournament_id=NEW.tournament_id
         AND o.eliminated_user_id=NEW.eliminated_user_id
         AND o.mode='mystery_chest' AND o.hand_id::text=NEW.hand_id;
      IF NEW.bounty_obligation_id IS NULL THEN
        RAISE EXCEPTION 'mystery award context does not match its exact generation'
          USING ERRCODE='check_violation';
      END IF;
      NEW.activation_generation := v_activation_generation;
    ELSIF EXISTS (
      SELECT 1 FROM public.tournament_bounty_obligations o
       WHERE o.tournament_id=NEW.tournament_id
         AND o.eliminated_user_id=NEW.eliminated_user_id
         AND o.mode='mystery_chest' AND o.hand_id::text=NEW.hand_id
    ) THEN
      RAISE EXCEPTION 'generation-bound mystery award has no exact obligation context'
        USING ERRCODE='check_violation';
    END IF;
  ELSE
    SELECT o.activation_generation INTO v_activation_generation
      FROM public.tournament_bounty_obligations o
     WHERE o.id=NEW.bounty_obligation_id AND o.tournament_id=NEW.tournament_id
       AND o.eliminated_user_id=NEW.eliminated_user_id
       AND o.mode='mystery_chest' AND o.hand_id::text=NEW.hand_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'mystery award names a mismatched obligation generation'
        USING ERRCODE='check_violation';
    END IF;
    NEW.activation_generation := v_activation_generation;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_freeze_batched_tournament_place()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_old_batched boolean := false;
  v_new_batched boolean := false;
  v_gate text := COALESCE(current_setting('app.atomic_tournament_place_batch', true), '');
BEGIN
  IF TG_OP IN ('UPDATE', 'DELETE')
     AND OLD.kind IN ('place', 'bubble_protection') THEN
    SELECT EXISTS (
      SELECT 1 FROM public.tournament_place_settlement_batches b
       WHERE b.tournament_id = OLD.tournament_id
    ) INTO v_old_batched;
  END IF;
  IF TG_OP IN ('INSERT', 'UPDATE')
     AND NEW.kind IN ('place', 'bubble_protection') THEN
    SELECT EXISTS (
      SELECT 1 FROM public.tournament_place_settlement_batches b
       WHERE b.tournament_id = NEW.tournament_id
    ) INTO v_new_batched;
  END IF;

  IF NOT v_old_batched AND NOT v_new_batched THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  /* The FK's parent cascade is the only legal delete after preparation. */
  IF TG_OP = 'DELETE'
     AND NOT EXISTS (SELECT 1 FROM public.tournaments t WHERE t.id = OLD.tournament_id) THEN
    RETURN OLD;
  END IF;

  /* Settlement only updates the already-frozen payment progress. It never
     creates, deletes, rekeys, changes a recipient or changes an entitlement. */
  IF TG_OP <> 'UPDATE' THEN
    RAISE EXCEPTION
      'tournament obligations frozen by an atomic place batch cannot be %', lower(TG_OP)
      USING ERRCODE = 'check_violation';
  END IF;
  IF ROW(NEW.id, NEW.tournament_id, NEW.kind, NEW.place, NEW.user_id,
         NEW.amount_owed, NEW.created_at, NEW.adjustment_id)
     IS DISTINCT FROM
     ROW(OLD.id, OLD.tournament_id, OLD.kind, OLD.place, OLD.user_id,
         OLD.amount_owed, OLD.created_at, OLD.adjustment_id) THEN
    RAISE EXCEPTION
      'a frozen place obligation identity, recipient or entitlement cannot change'
      USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.kind = 'bubble_protection'
     AND NEW.source IS DISTINCT FROM OLD.source THEN
    RAISE EXCEPTION
      'a frozen Bubble Protection obligation source cannot change'
      USING ERRCODE = 'check_violation';
  END IF;
  IF v_gate <> OLD.tournament_id::text THEN
    RAISE EXCEPTION
      'tournament obligations for tournament % are frozen by their atomic place batch',
      OLD.tournament_id
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.amount_paid + 0.005 < OLD.amount_paid
     OR (OLD.settled_at IS NOT NULL AND NEW.settled_at IS DISTINCT FROM OLD.settled_at) THEN
    RAISE EXCEPTION
      'a frozen place obligation payment record cannot move backwards'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_freeze_atomic_final_table_deal_obligation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_old_batched boolean := false;
  v_new_batched boolean := false;
  v_gate text := COALESCE(current_setting('app.atomic_final_table_deal_batch', true), '');
BEGIN
  IF TG_OP IN ('UPDATE', 'DELETE')
     AND OLD.kind IN ('place', 'final_table_deal', 'bubble_protection') THEN
    SELECT EXISTS (
      SELECT 1 FROM public.tournament_final_table_deal_batches b
       WHERE b.tournament_id = OLD.tournament_id
    ) INTO v_old_batched;
  END IF;
  IF TG_OP IN ('INSERT', 'UPDATE')
     AND NEW.kind IN ('place', 'final_table_deal', 'bubble_protection') THEN
    SELECT EXISTS (
      SELECT 1 FROM public.tournament_final_table_deal_batches b
       WHERE b.tournament_id = NEW.tournament_id
    ) INTO v_new_batched;
  END IF;

  IF NOT v_old_batched AND NOT v_new_batched THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  IF TG_OP = 'DELETE'
     AND NOT EXISTS (SELECT 1 FROM public.tournaments t WHERE t.id = OLD.tournament_id) THEN
    RETURN OLD;
  END IF;

  IF TG_OP <> 'UPDATE' THEN
    RAISE EXCEPTION
      'obligations frozen by an atomic final-table deal cannot be %', lower(TG_OP)
      USING ERRCODE = 'check_violation';
  END IF;
  IF ROW(NEW.id, NEW.tournament_id, NEW.kind, NEW.place, NEW.user_id,
         NEW.amount_owed, NEW.source, NEW.created_at, NEW.adjustment_id)
     IS DISTINCT FROM
     ROW(OLD.id, OLD.tournament_id, OLD.kind, OLD.place, OLD.user_id,
         OLD.amount_owed, OLD.source, OLD.created_at, OLD.adjustment_id) THEN
    RAISE EXCEPTION
      'a frozen final-table-deal obligation identity, recipient or entitlement cannot change'
      USING ERRCODE = 'check_violation';
  END IF;
  -- Only the exact lifecycle marker may change after canonical v2 completion.
  IF OLD.terminal_closed_at IS NULL AND NEW.terminal_closed_at IS NOT NULL
    AND isfinite(NEW.terminal_closed_at)
    AND (to_jsonb(NEW)-'terminal_closed_at') IS NOT DISTINCT FROM
        (to_jsonb(OLD)-'terminal_closed_at')
    AND EXISTS(SELECT 1 FROM public.tournament_final_table_deal_batches b
      WHERE b.tournament_id=OLD.tournament_id AND b.contract_version=2 AND b.settled_at IS NOT NULL)
    AND EXISTS(SELECT 1 FROM public.tournaments t
      WHERE t.id=OLD.tournament_id AND upper(t.status::text)='COMPLETED'
       AND t.ended_at IS NOT DISTINCT FROM NEW.terminal_closed_at) THEN
    PERFORM public.fn_ca_verify_terminal_final_deal_batch(OLD.tournament_id,true);
    RETURN NEW;
  END IF;
  IF v_gate <> OLD.tournament_id::text THEN
    RAISE EXCEPTION
      'final-table-deal obligations for tournament % are frozen by their atomic batch',
      OLD.tournament_id
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.amount_paid + 0.005 < OLD.amount_paid
     OR NEW.amount_paid > NEW.amount_owed + 0.005
     OR (OLD.settled_at IS NOT NULL AND NEW.settled_at IS DISTINCT FROM OLD.settled_at) THEN
    RAISE EXCEPTION
      'a frozen final-table-deal payment record cannot move backwards or above its entitlement'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_spin_reserve_row_requires_exact_journal()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_pool_id uuid;
  v_count integer;
  v_key text;
  v_category text;
  v_from_type text;
  v_from_id uuid;
  v_to_type text;
  v_to_id uuid;
  v_original public.spin_reserve_ledger%ROWTYPE;
BEGIN
  IF NEW.tournament_id IS NULL
     OR NEW.kind NOT IN (
       'contribution','jackpot_draw','draw_reversal',
       'contribution_reversal') THEN
    RETURN NEW;
  END IF;
  IF NEW.amount IS NULL
     OR NEW.amount::text IN ('NaN','Infinity','-Infinity')
     OR NEW.amount IS DISTINCT FROM round(NEW.amount,2)
     OR NEW.balance_after IS NULL
     OR NEW.balance_after::text IN ('NaN','Infinity','-Infinity')
     OR NEW.balance_after IS DISTINCT FROM round(NEW.balance_after,2) THEN
    RAISE EXCEPTION 'Spin reserve evidence has invalid money'
      USING ERRCODE = '23514';
  END IF;
  SELECT p.id INTO v_pool_id FROM public.spin_bonus_pools p
   WHERE p.club_id = NEW.club_id;
  IF v_pool_id IS NULL THEN
    RAISE EXCEPTION 'Spin reserve row has no pool for owner %',NEW.club_id
      USING ERRCODE = 'P0404';
  END IF;

  IF NEW.kind IN ('contribution','jackpot_draw') THEN
    IF NEW.buy_in IS NULL OR NEW.buy_in <= 0
       OR NEW.seats IS DISTINCT FROM 3
       OR (NEW.kind = 'contribution' AND (
            NEW.amount <= 0 OR NEW.house_rake IS NULL OR NEW.house_rake < 0
            OR NEW.amount IS DISTINCT FROM
                 round(NEW.buy_in*3-NEW.house_rake,2)))
       OR (NEW.kind = 'jackpot_draw' AND (
            NEW.amount >= 0 OR NEW.multiplier IS NULL OR NEW.multiplier <= 0
            OR round(-NEW.amount,2) IS DISTINCT FROM
                 round(NEW.buy_in*NEW.multiplier,2))) THEN
      RAISE EXCEPTION 'Spin % violates its exact funded contract',NEW.kind
        USING ERRCODE = '23514';
    END IF;
  ELSE
    SELECT * INTO v_original FROM public.spin_reserve_ledger r
     WHERE r.tournament_id = NEW.tournament_id
       AND r.kind = CASE WHEN NEW.kind = 'draw_reversal'
                         THEN 'jackpot_draw' ELSE 'contribution' END
     FOR SHARE;
    IF v_original.id IS NULL
       OR v_original.club_id IS DISTINCT FROM NEW.club_id
       OR NEW.buy_in IS DISTINCT FROM v_original.buy_in
       OR NEW.seats IS DISTINCT FROM v_original.seats
       OR NEW.house_rake IS DISTINCT FROM v_original.house_rake
       OR NEW.multiplier IS DISTINCT FROM v_original.multiplier
       OR NEW.amount IS DISTINCT FROM -v_original.amount
       OR (NEW.kind = 'draw_reversal' AND NEW.amount <= 0)
       OR (NEW.kind = 'contribution_reversal' AND NEW.amount >= 0) THEN
      RAISE EXCEPTION 'Spin % does not reverse one exact original row',NEW.kind
        USING ERRCODE = 'P0404';
    END IF;
  END IF;

  v_key := 'spin:' || NEW.tournament_id::text || CASE NEW.kind
    WHEN 'contribution' THEN ':entry'
    WHEN 'jackpot_draw' THEN ':draw'
    WHEN 'draw_reversal' THEN ':cancel:draw'
    ELSE ':cancel:entry' END;
  v_category := CASE NEW.kind
    WHEN 'contribution' THEN 'spin_entry'
    WHEN 'jackpot_draw' THEN 'spin_prize'
    ELSE 'reversal' END;
  v_from_type := CASE NEW.kind
    WHEN 'contribution' THEN 'prize_liability'
    WHEN 'draw_reversal' THEN 'prize_liability'
    ELSE 'spin_reserve' END;
  v_from_id := CASE WHEN v_from_type = 'prize_liability'
                    THEN NEW.tournament_id ELSE v_pool_id END;
  v_to_type := CASE WHEN v_from_type = 'prize_liability'
                    THEN 'spin_reserve' ELSE 'prize_liability' END;
  v_to_id := CASE WHEN v_to_type = 'prize_liability'
                  THEN NEW.tournament_id ELSE v_pool_id END;

  SELECT count(*) INTO v_count FROM public.chip_ledger l
   WHERE l.category = v_category
     AND l.from_type = v_from_type AND l.from_entity_id = v_from_id
     AND l.to_type = v_to_type AND l.to_entity_id = v_to_id
     AND l.tournament_id = NEW.tournament_id
     AND (l.idempotency_key = v_key
          OR (NEW.kind = 'jackpot_draw' AND l.idempotency_key IS NULL))
     AND l.amount = abs(NEW.amount)
     AND CASE WHEN NEW.amount > 0
              THEN l.post_to_balance IS NOT DISTINCT FROM NEW.balance_after
              ELSE l.post_from_balance IS NOT DISTINCT FROM NEW.balance_after END;
  IF v_count <> 1 THEN
    RAISE EXCEPTION 'Spin % requires one exact journal leg; found %',
      NEW.kind,v_count USING ERRCODE = 'P0404';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_terminal_bounty_recipient_is_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_old_tournament_id uuid;
  v_new_tournament_id uuid;
  v_old_marker timestamptz;
  v_new_marker timestamptz;
  v_new_status text;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.award_id IS DISTINCT FROM OLD.award_id THEN
    RAISE EXCEPTION 'bounty recipient award ownership is immutable'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP <> 'INSERT' THEN
    SELECT a.tournament_id INTO v_old_tournament_id
      FROM public.tournament_bounty_awards a WHERE a.id = OLD.award_id;
  END IF;
  IF TG_OP <> 'DELETE' THEN
    SELECT a.tournament_id INTO v_new_tournament_id
      FROM public.tournament_bounty_awards a WHERE a.id = NEW.award_id;
  END IF;
  IF TG_OP <> 'INSERT' THEN v_old_marker := OLD.terminal_closed_at; END IF;
  IF TG_OP <> 'DELETE' THEN v_new_marker := NEW.terminal_closed_at; END IF;
  IF TG_OP = 'INSERT' AND v_new_marker IS NOT NULL THEN
    RAISE EXCEPTION 'new bounty recipient cannot supply a terminal marker'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP <> 'INSERT' AND v_old_marker IS NOT NULL THEN
    RAISE EXCEPTION 'terminal bounty recipient evidence is immutable'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'UPDATE' AND v_new_marker IS DISTINCT FROM v_old_marker THEN
    IF public.fn_ca_terminal_marker_transition_is_exact(
         to_jsonb(OLD),to_jsonb(NEW),v_old_tournament_id) THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'bounty recipient terminal marker transition is not canonical'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'INSERT' AND v_new_tournament_id IS NOT NULL THEN
    SELECT upper(COALESCE(t.status::text,'')) INTO v_new_status
      FROM public.tournaments t
     WHERE t.id = v_new_tournament_id FOR SHARE;
    IF v_new_status IN ('COMPLETED','CANCELLED','CANCELED') THEN
      RAISE EXCEPTION 'terminal bounty recipient evidence is immutable'
        USING ERRCODE = '55000';
    END IF;
  END IF;
  IF public.fn_ca_has_committed_tournament_receipt(v_old_tournament_id)
     OR public.fn_ca_has_committed_tournament_receipt(v_new_tournament_id) THEN
    RAISE EXCEPTION 'terminal bounty recipient evidence is immutable'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_terminal_credit_key_is_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_old_tournament_id uuid;
  v_new_tournament_id uuid;
  v_new_status text;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.key IS DISTINCT FROM OLD.key THEN
    RAISE EXCEPTION 'wallet credit idempotency keys are immutable'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP <> 'INSERT' THEN
    v_old_tournament_id := public.fn_ca_tournament_id_from_credit_key(OLD.key);
  END IF;
  IF TG_OP <> 'DELETE' THEN
    v_new_tournament_id := public.fn_ca_tournament_id_from_credit_key(NEW.key);
  END IF;
  -- Recognized payout claims are append-only financial evidence. An existing
  -- row is already locked before this row trigger runs, so UPDATE/DELETE must
  -- refuse immediately instead of reversing the terminal root lock order.
  IF TG_OP <> 'INSERT'
     AND COALESCE(v_old_tournament_id,v_new_tournament_id) IS NOT NULL THEN
    RAISE EXCEPTION 'tournament wallet credit claims are append-only'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'INSERT' AND v_new_tournament_id IS NOT NULL THEN
    SELECT upper(COALESCE(t.status::text,'')) INTO v_new_status
      FROM public.tournaments t
     WHERE t.id = v_new_tournament_id FOR SHARE;
    IF v_new_status IN ('COMPLETED','CANCELLED','CANCELED') THEN
      RAISE EXCEPTION 'terminal wallet credit key evidence is immutable'
        USING ERRCODE = '55000';
    END IF;
  END IF;
  IF v_new_tournament_id IS NOT NULL
     AND v_new_tournament_id IS DISTINCT FROM v_old_tournament_id THEN
    PERFORM 1 FROM public.tournaments t
     WHERE t.id = v_new_tournament_id FOR SHARE;
  END IF;
  IF public.fn_ca_has_committed_tournament_receipt(v_old_tournament_id)
     OR public.fn_ca_has_committed_tournament_receipt(v_new_tournament_id) THEN
    RAISE EXCEPTION 'terminal wallet credit key evidence is immutable'
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

