CREATE OR REPLACE FUNCTION public.fn_sync_profile_total_hands()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_user uuid := COALESCE(NEW.user_id, OLD.user_id);
BEGIN
  IF v_user IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  /* Recomputed from the table rather than incremented. An increment has to be
     right on every path - insert, update, delete, and the upsert the
     achievement engine uses - and being wrong once is permanent. A SUM over a
     handful of club rows for one player is cheap and cannot drift. */
  UPDATE public.profiles p
     SET total_hands_played = COALESCE((
           SELECT sum(s.hands_played) FROM public.player_stats s WHERE s.user_id = v_user
         ), 0)
   WHERE p.id = v_user;

  RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_vip_points_move_only_with_a_leg()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_writer text := NULLIF(current_setting('app.vip_points_writer', true), '');
BEGIN
  IF NEW.current_points < 0 THEN
    RAISE EXCEPTION 'vip_points.current_points cannot go negative (% for %)', NEW.current_points, NEW.user_id
      USING ERRCODE = 'P0403';
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF (NEW.current_points <> 0 OR NEW.lifetime_points <> 0) AND v_writer IS NULL THEN
      RAISE EXCEPTION 'a vip_points row is born at zero unless a ledger writer (fn_award_vip_credit) creates it with its first leg'
        USING ERRCODE = 'P0403';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.lifetime_points < OLD.lifetime_points THEN
    RAISE EXCEPTION 'vip_points.lifetime_points cannot shrink (% -> % for %)', OLD.lifetime_points, NEW.lifetime_points, NEW.user_id
      USING ERRCODE = 'P0403';
  END IF;
  IF (NEW.current_points IS DISTINCT FROM OLD.current_points OR NEW.lifetime_points IS DISTINCT FROM OLD.lifetime_points)
     AND v_writer IS NULL THEN
    RAISE EXCEPTION
      'vip_points for % moves only through fn_award_vip_credit or fn_redeem_vip_points, which write the leg in the same transaction. A balance with no leg is the defect this guard exists for.',
      NEW.user_id USING ERRCODE = 'P0403';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fn_attach_bounty_ledger_obligation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_context text := current_setting('app.bounty_obligation_id',true);
  v_obligation_id uuid;
  /* A REVEALED MYSTERY BOUNTY MAY NAME ITS OWN OBLIGATION (2026-09-10).
     A paid mystery chest is a bounty ledger entry like any other and its
     provenance is the mystery obligation. Only a row that says so may name
     one; a regular bounty still cannot borrow a mystery generation. */
  v_mystery_ok boolean := COALESCE(NEW.is_mystery_revealed, false);
BEGIN
  IF NEW.bounty_obligation_id IS NULL THEN
    IF COALESCE(v_context,'')
         ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_obligation_id := v_context::uuid;
      SELECT o.id INTO NEW.bounty_obligation_id
        FROM public.tournament_bounty_obligations o
       WHERE o.id=v_obligation_id AND o.tournament_id=NEW.tournament_id
         AND o.eliminated_user_id=NEW.eliminated_player_id
         AND (o.mode<>'mystery_chest' OR v_mystery_ok);
      IF NEW.bounty_obligation_id IS NULL THEN
        RAISE EXCEPTION 'bounty ledger context does not match its exact generation'
          USING ERRCODE='check_violation';
      END IF;
    ELSIF EXISTS (
      SELECT 1 FROM public.tournament_bounty_obligations o
       WHERE o.tournament_id=NEW.tournament_id
         AND o.eliminated_user_id=NEW.eliminated_player_id
         AND o.mode<>'mystery_chest' AND o.state='pending'
    ) THEN
      RAISE EXCEPTION 'generation-bound bounty ledger insert has no exact obligation context'
        USING ERRCODE='check_violation';
    END IF;
  ELSIF NOT EXISTS (
    SELECT 1 FROM public.tournament_bounty_obligations o
     WHERE o.id=NEW.bounty_obligation_id AND o.tournament_id=NEW.tournament_id
       AND o.eliminated_user_id=NEW.eliminated_player_id
       AND (o.mode<>'mystery_chest' OR v_mystery_ok)
  ) THEN
    RAISE EXCEPTION 'bounty ledger names a mismatched obligation generation'
      USING ERRCODE='check_violation';
  END IF;
  RETURN NEW;
END;
$function$

