$function$

CREATE OR REPLACE FUNCTION public.fn_ca_bomb_hand_keeps_its_award_units()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_distributable numeric;
  v_units numeric;
  v_n int;
BEGIN
  IF NEW.bomb_pot IS NULL THEN RETURN NULL; END IF;

  v_distributable := round(COALESCE(NEW.pot_size,0)
                           - COALESCE(NEW.rake_amount,0)
                           - COALESCE(NEW.bbj_amount,0), 2);
  /* Nothing to distribute means nothing to attribute: a folded-around bomb, or
     a hand voided before showdown. Not every bomb row owes a breakdown. */
  IF v_distributable <= 0 THEN RETURN NULL; END IF;

  SELECT COALESCE(round(sum(amount),2),0), count(*)
    INTO v_units, v_n
    FROM public.bomb_pot_award_units
   WHERE hand_history_id = NEW.id;

  IF v_n = 0 THEN
    RAISE EXCEPTION
      'bomb pot hand #% (%) would commit with % chips distributed and no award units. '
      'Write the hand and its units together through fn_ca_insert_hand_with_awards - '
      'two separate writes is how 18 bomb pots lost their record in the week to '
      '2026-09-06.',
      NEW.hand_number, NEW.id, v_distributable
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;

  IF v_units <> v_distributable THEN
    RAISE EXCEPTION
      'bomb pot hand #% (%) distributes % chips but its % award unit(s) sum to %.',
      NEW.hand_number, NEW.id, v_distributable, v_n, v_units
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;

  RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.fn_guard_retired_club_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_club_id uuid;
  v_old_club_id uuid;
  v_maintenance boolean :=
    auth.uid() IS NULL
    AND coalesce(current_setting('app.club_retirement_maintenance', true), '') = 'on';
BEGIN
  IF v_maintenance THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'DELETE' THEN
    IF TG_TABLE_NAME = 'unions' THEN
      v_club_id := OLD.id;
    ELSIF TG_TABLE_NAME = 'table_seats' THEN
      SELECT t.club_id INTO v_club_id FROM public.tables t WHERE t.id = OLD.table_id;
    ELSIF TG_TABLE_NAME IN ('tournament_players', 'tournament_escrow') THEN
      SELECT t.club_id INTO v_club_id FROM public.tournaments t
       WHERE t.id = OLD.tournament_id;
    ELSIF TG_TABLE_NAME = 'chip_escrow' THEN
      SELECT cr.club_id INTO v_club_id FROM public.cashout_requests cr
       WHERE cr.id = OLD.cashout_request_id;
    ELSIF TG_TABLE_NAME = 'credit_invoices' THEN
      SELECT a.club_id INTO v_club_id FROM public.agents a WHERE a.id = OLD.agent_id;
    ELSE
      v_club_id := OLD.club_id;
    END IF;
  ELSE
    IF TG_TABLE_NAME = 'unions' THEN
      v_club_id := NEW.id;
    ELSIF TG_TABLE_NAME = 'table_seats' THEN
      SELECT t.club_id INTO v_club_id FROM public.tables t WHERE t.id = NEW.table_id;
    ELSIF TG_TABLE_NAME IN ('tournament_players', 'tournament_escrow') THEN
      SELECT t.club_id INTO v_club_id FROM public.tournaments t
       WHERE t.id = NEW.tournament_id;
    ELSIF TG_TABLE_NAME = 'chip_escrow' THEN
      SELECT cr.club_id INTO v_club_id FROM public.cashout_requests cr
       WHERE cr.id = NEW.cashout_request_id;
    ELSIF TG_TABLE_NAME = 'credit_invoices' THEN
      SELECT a.club_id INTO v_club_id FROM public.agents a WHERE a.id = NEW.agent_id;
    ELSE
      v_club_id := NEW.club_id;
    END IF;

    -- On UPDATE, check the source scope too. Moving a retained row to an active
    -- club must not become an escape hatch from a retired club's write freeze.
    IF TG_OP = 'UPDATE' THEN
      IF TG_TABLE_NAME = 'unions' THEN
        v_old_club_id := OLD.id;
      ELSIF TG_TABLE_NAME = 'table_seats' THEN
        SELECT t.club_id INTO v_old_club_id FROM public.tables t WHERE t.id = OLD.table_id;
      ELSIF TG_TABLE_NAME IN ('tournament_players', 'tournament_escrow') THEN
        SELECT t.club_id INTO v_old_club_id FROM public.tournaments t
         WHERE t.id = OLD.tournament_id;
      ELSIF TG_TABLE_NAME = 'chip_escrow' THEN
        SELECT cr.club_id INTO v_old_club_id FROM public.cashout_requests cr
         WHERE cr.id = OLD.cashout_request_id;
      ELSIF TG_TABLE_NAME = 'credit_invoices' THEN
        SELECT a.club_id INTO v_old_club_id FROM public.agents a WHERE a.id = OLD.agent_id;
      ELSE
        v_old_club_id := OLD.club_id;
      END IF;
    END IF;
  END IF;

  -- A union row can use a club UUID without an FK back to clubs. Serialize
  -- that conversion with the retirement RPC so it cannot create a union
  -- identity from a club that became retired in the same instant.
  IF TG_TABLE_NAME = 'unions' AND v_club_id IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(
      hashtextextended('cashier-hierarchy:' || v_club_id::text, 0)
    );
  END IF;

  IF (v_club_id IS NOT NULL OR v_old_club_id IS NOT NULL) AND EXISTS (
    SELECT 1 FROM public.clubs c
     WHERE c.id IN (v_club_id, v_old_club_id) AND c.lifecycle_status = 'retired'
  ) THEN
    RAISE EXCEPTION 'CLUB_RETIRED: gameplay and cashier records are read-only'
      USING ERRCODE = '55000';
  END IF;

  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.fn_refuse_completed_with_pending_bounties()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.status = 'COMPLETED' AND OLD.status IS DISTINCT FROM 'COMPLETED'
     AND (COALESCE(NEW.is_bounty,false) OR COALESCE(NEW.is_pko,false)
          OR COALESCE(NEW.is_mystery_bounty,false)) THEN
    IF public.fn_tournament_has_unsettled_bounties(NEW.id) THEN
      RAISE EXCEPTION 'tournament % has pending bounty obligations', NEW.id
        USING ERRCODE='check_violation';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.tournament_bounty_completion_receipts r
                    WHERE r.tournament_id=NEW.id AND r.pool_finalized_at IS NOT NULL) THEN
      RAISE EXCEPTION 'tournament % bounty pool has not been finalized', NEW.id
        USING ERRCODE='check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_refuse_mystery_activation_with_pending_heads()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.mystery_bounty_stage = 'active'
     AND OLD.mystery_bounty_stage IS DISTINCT FROM 'active' THEN
    IF public.fn_tournament_has_unsettled_bounties(NEW.id) THEN
      RAISE EXCEPTION 'tournament % has pending pre-mystery bounty obligations', NEW.id
        USING ERRCODE='check_violation';
    END IF;
    NEW.mystery_bounty_activation_generation :=
      OLD.mystery_bounty_activation_generation + 1;
  ELSIF NEW.mystery_bounty_activation_generation
            IS DISTINCT FROM OLD.mystery_bounty_activation_generation THEN
    RAISE EXCEPTION 'mystery activation generation is database-managed'
      USING ERRCODE='check_violation';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_receipt_mystery_activation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_chest_count integer;
  v_pool_cents bigint;
  v_receipt public.tournament_mystery_activation_receipts%ROWTYPE;
BEGIN
  IF NEW.mystery_bounty_stage='active'
     AND OLD.mystery_bounty_stage IS DISTINCT FROM 'active' THEN
    SELECT count(*)::integer,COALESCE(sum(c.amount_cents),0)::bigint
      INTO v_chest_count,v_pool_cents
      FROM public.tournament_bounty_chests c WHERE c.tournament_id=NEW.id;
    IF v_chest_count<=0 OR v_pool_cents<=0
       OR v_pool_cents IS DISTINCT FROM NEW.mystery_bounty_pool_cents THEN
      RAISE EXCEPTION 'mystery activation inventory is missing or does not match its sealed pool'
        USING ERRCODE='check_violation';
    END IF;
    INSERT INTO public.tournament_mystery_activation_receipts
      (tournament_id,activation_generation,activated_at,chest_count,pool_cents)
    VALUES (NEW.id,NEW.mystery_bounty_activation_generation,
            COALESCE(NEW.mystery_bounty_activated_at,now()),v_chest_count,v_pool_cents)
    ON CONFLICT (tournament_id,activation_generation) DO NOTHING;
    SELECT * INTO v_receipt FROM public.tournament_mystery_activation_receipts
     WHERE tournament_id=NEW.id
       AND activation_generation=NEW.mystery_bounty_activation_generation;
    IF NOT FOUND OR v_receipt.chest_count<>v_chest_count
       OR v_receipt.pool_cents<>v_pool_cents THEN
      RAISE EXCEPTION 'mystery activation receipt identity conflict'
        USING ERRCODE='check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_guard_atomic_satellite_completion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_check jsonb;
BEGIN
  IF NEW.status='COMPLETED' AND OLD.status IS DISTINCT FROM 'COMPLETED'
     AND (lower(COALESCE(NEW.variant,''))='satellite'
       OR upper(COALESCE(NEW.tournament_type,''))='SATELLITE'
       OR NEW.satellite_target_id IS NOT NULL) THEN
    IF OLD.status<>'COMPLETING' THEN
      RAISE EXCEPTION 'satellite tournament cannot complete from %',OLD.status
        USING ERRCODE='check_violation';
    END IF;
    v_check:=public.fn_check_atomic_satellite_finish(NEW.id);
    IF COALESCE((v_check->>'ok')::boolean,false) IS NOT TRUE THEN
      RAISE EXCEPTION 'satellite completion has no exact atomic receipt: %',v_check
        USING ERRCODE='check_violation';
    END IF;
    NEW.on_break:=false;
    NEW.break_started_at:=NULL;
    NEW.break_ends_at:=NULL;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_guard_tournament_completing_claim()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_kind text;
  v_finish public.tournament_finish_receipts%ROWTYPE;
BEGIN
  IF NEW.status = 'COMPLETING' AND OLD.status IS DISTINCT FROM 'COMPLETING' THEN
    IF OLD.status IS DISTINCT FROM 'RUNNING' THEN
      RAISE EXCEPTION 'tournament % cannot claim completion from status %',
        NEW.id, OLD.status USING ERRCODE = 'check_violation';
    END IF;

    v_kind := public.fn_tournament_finish_kind(NEW.id);
    IF v_kind = 'final_table_deal' AND NOT EXISTS (
      SELECT 1 FROM public.tournament_final_table_deal_batches b
       WHERE b.tournament_id=NEW.id AND b.contract_version=2
    ) THEN
      IF current_setting('app.atomic_final_table_deal_batch', true)
           IS DISTINCT FROM NEW.id::text THEN
        RAISE EXCEPTION 'final-table-deal tournament % has no atomic claim owner', NEW.id
          USING ERRCODE = 'check_violation';
      END IF;
      RETURN NEW;
    END IF;

    IF v_kind = 'final_table_deal' THEN
      PERFORM public.fn_ca_verify_terminal_final_deal_batch(NEW.id,false);
    END IF;

    SELECT * INTO v_finish
      FROM public.tournament_finish_receipts f
     WHERE f.tournament_id = NEW.id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'tournament % cannot enter COMPLETING without an immutable finish claim',
        NEW.id USING ERRCODE = 'check_violation';
    END IF;
    IF v_finish.finish_kind IS DISTINCT FROM v_kind THEN
      RAISE EXCEPTION 'tournament % COMPLETING claim has format conflict', NEW.id
        USING ERRCODE = 'check_violation';
    END IF;
    IF current_setting('app.tournament_finish_claim', true)
         IS DISTINCT FROM NEW.id::text THEN
      RAISE EXCEPTION 'tournament % COMPLETING claim has no RPC owner', NEW.id
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_receipted_tournament_is_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF upper(COALESCE(OLD.status::text,'')) IN
       ('COMPLETED','CANCELLED','CANCELED') THEN
    RAISE EXCEPTION 'terminal tournament % is immutable after closure',OLD.id
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_non_satellite_completed_requires_terminal_receipt()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF upper(COALESCE(NEW.status::text,'')) <> 'COMPLETED' THEN
    RETURN NEW;
  END IF;
  IF lower(COALESCE(NEW.variant::text,'')) = 'satellite'
     OR upper(COALESCE(NEW.tournament_type::text,'')) = 'SATELLITE'
     OR NEW.satellite_target_id IS NOT NULL
     OR NEW.satellite_target IS NOT NULL THEN
    RETURN NEW;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.tournament_terminal_settlements h
     WHERE h.tournament_id = NEW.id
  ) THEN
    RAISE EXCEPTION
      'non-satellite tournament % cannot become COMPLETED without its atomic terminal receipt',
      NEW.id USING ERRCODE = '55000';
  END IF;
  PERFORM public.fn_ca_tournament_terminal_receipt(NEW.id,NULL);
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_guard_tournament_prize_math_contract()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_unit integer;
BEGIN
  IF TG_OP='UPDATE' THEN
    -- Legacy club routing remains governed by its existing contract guards.
    -- This trigger freezes denomination only for an explicitly versioned ladder.
    IF OLD.payout_math_version=1 AND NEW.payout_math_version=1
       AND OLD.payout_unit_cents=1 AND NEW.payout_unit_cents=1 THEN RETURN NEW; END IF;
    IF ROW(NEW.payout_math_version,NEW.payout_unit_cents,NEW.club_id) IS NOT DISTINCT FROM
       ROW(OLD.payout_math_version,OLD.payout_unit_cents,OLD.club_id) THEN RETURN NEW; END IF;
    IF COALESCE(OLD.entry_contract_locked,false) OR COALESCE(OLD.prize_pool_finalized,false)
       OR OLD.started_at IS NOT NULL
       OR upper(COALESCE(OLD.status,'')) NOT IN('ANNOUNCED','REGISTERING','SCHEDULED')
       OR upper(COALESCE(NEW.status,'')) NOT IN('ANNOUNCED','REGISTERING','SCHEDULED')
       OR EXISTS(SELECT 1 FROM public.tournament_players tp WHERE tp.tournament_id=OLD.id)
       OR EXISTS(SELECT 1 FROM public.tournament_payouts tp WHERE tp.tournament_id=OLD.id)
       OR EXISTS(SELECT 1 FROM public.tournament_launch_receipts lr WHERE lr.tournament_id=OLD.id) THEN
      RAISE EXCEPTION 'Tournament prize arithmetic is frozen after entry or launch'
        USING ERRCODE='23514';
    END IF;
  END IF;
  IF NEW.payout_math_version=2 THEN
    SELECT CASE WHEN c.asset='diamonds' AND c.is_platform IS TRUE AND c.union_id IS NULL
                THEN 100 ELSE 1 END INTO v_unit FROM public.clubs c WHERE c.id=NEW.club_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Prize contract requires an existing club' USING ERRCODE='23503'; END IF;
    -- The club determines denomination; a caller cannot request fractional Diamonds.
    NEW.payout_unit_cents:=v_unit;
  ELSE
    NEW.payout_unit_cents:=1;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_guard_new_mtt_blind_contract()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE contract jsonb;
BEGIN
  IF upper(COALESCE(NEW.tournament_type,''))<>'MTT'
     OR lower(COALESCE(NEW.variant,'')) IN ('spin','sng')
     OR COALESCE(NEW.max_players,0)<=2 THEN RETURN NEW; END IF;
  IF TG_OP='UPDATE' AND NEW.blind_structure IS NOT DISTINCT FROM OLD.blind_structure
     AND NEW.starting_chips IS NOT DISTINCT FROM OLD.starting_chips
     AND upper(COALESCE(OLD.tournament_type,''))='MTT'
     AND lower(COALESCE(OLD.variant,'')) NOT IN ('spin','sng')
     AND COALESCE(OLD.max_players,0)>2 THEN RETURN NEW; END IF;
  contract:=public.fn_ca_mtt_blind_contract(NEW.blind_structure,NEW.starting_chips);
  NEW.blind_speed:=contract->>'blind_speed';
  NEW.is_turbo:=(contract->>'is_turbo')::boolean;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_guard_tournament_mystery_creation_contract()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_expected jsonb; v_actual jsonb;
BEGIN
  IF TG_OP='UPDATE' AND coalesce(OLD.is_mystery_bounty,false)
     AND OLD.mystery_bounty_stage IS DISTINCT FROM 'pending'
     AND ROW(NEW.is_mystery_bounty,NEW.mystery_bounty_profile,NEW.mystery_bounty_activation,NEW.mystery_bounty_activation_value,
       NEW.mystery_bounty_pool_percent,NEW.mystery_bounty_regular_pool_percent,NEW.mystery_bounty_top_percent)
     IS DISTINCT FROM ROW(OLD.is_mystery_bounty,OLD.mystery_bounty_profile,OLD.mystery_bounty_activation,OLD.mystery_bounty_activation_value,
       OLD.mystery_bounty_pool_percent,OLD.mystery_bounty_regular_pool_percent,OLD.mystery_bounty_top_percent) THEN
    RAISE EXCEPTION 'Mystery bounty terms cannot change after activation' USING ERRCODE='55000';
  END IF;
  IF NOT coalesce(NEW.is_mystery_bounty,false) THEN RETURN NEW; END IF;
  IF TG_OP='UPDATE' AND coalesce(OLD.is_mystery_bounty,false)
     AND ROW(NEW.mystery_bounty_profile,NEW.mystery_bounty_activation,NEW.mystery_bounty_activation_value,
       NEW.mystery_bounty_pool_percent,NEW.mystery_bounty_regular_pool_percent,NEW.mystery_bounty_top_percent)
     IS NOT DISTINCT FROM ROW(OLD.mystery_bounty_profile,OLD.mystery_bounty_activation,OLD.mystery_bounty_activation_value,
       OLD.mystery_bounty_pool_percent,OLD.mystery_bounty_regular_pool_percent,OLD.mystery_bounty_top_percent)
    THEN RETURN NEW; END IF;
  IF TG_OP='UPDATE' AND OLD.mystery_bounty_stage IS DISTINCT FROM 'pending' THEN
    RAISE EXCEPTION 'Mystery bounty terms cannot change after activation' USING ERRCODE='55000';
  END IF;
  v_expected:=public.fn_mystery_bounty_creation_document(jsonb_build_object(
    'mysteryBountyProfile',NEW.mystery_bounty_profile,'mysteryBountyActivation',NEW.mystery_bounty_activation,
    'mysteryBountyActivationValue',NEW.mystery_bounty_activation_value,
    'mysteryBountyPoolPercent',NEW.mystery_bounty_pool_percent,'mysteryBountyTopPercent',NEW.mystery_bounty_top_percent));
  IF NEW.mystery_bounty_regular_pool_percent IS DISTINCT FROM
     (v_expected->>'mystery_bounty_regular_pool_percent')::numeric THEN
    RAISE EXCEPTION 'Mystery bounty pool percentages must total 100' USING ERRCODE='22023';
  END IF;
  v_actual:=jsonb_build_object('mystery_bounty_profile',NEW.mystery_bounty_profile,
    'mystery_bounty_activation',NEW.mystery_bounty_activation,
    'mystery_bounty_activation_value',NEW.mystery_bounty_activation_value,
    'mystery_bounty_pool_percent',NEW.mystery_bounty_pool_percent,
    'mystery_bounty_regular_pool_percent',NEW.mystery_bounty_regular_pool_percent,
    'mystery_bounty_top_percent',NEW.mystery_bounty_top_percent);
  IF v_actual IS DISTINCT FROM v_expected THEN
    RAISE EXCEPTION 'Invalid canonical mystery bounty configuration' USING ERRCODE='22023';
  END IF;
  RETURN NEW;
END;
$function$

