CREATE OR REPLACE FUNCTION public.fn_check_club_message_permission()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    conv_category TEXT;
    conv_club_id UUID;
BEGIN
    -- Get conversation details
    SELECT category, club_id INTO conv_category, conv_club_id
    FROM conversations
    WHERE id = NEW.conversation_id;

    -- If not a club conversation, allow (personal messages have different rules)
    IF conv_category != 'club' OR conv_club_id IS NULL THEN
        RETURN NEW;
    END IF;

    -- Check permission
    IF NOT fn_can_message_in_club(NEW.sender_id, NEW.receiver_id, conv_club_id) THEN
        RAISE EXCEPTION 'Not authorized to message this user in this club';
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_live_streams_guard_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  is_end_user boolean := current_user = 'authenticated';
BEGIN
  -- broadcaster_id immutable for ALL callers
  IF NEW.broadcaster_id IS DISTINCT FROM OLD.broadcaster_id THEN
    RAISE EXCEPTION 'broadcaster_id is immutable'
      USING ERRCODE = '42501';
  END IF;

  -- Metric columns are SERVER-managed only (RPC path with SECURITY DEFINER
  -- runs as the function owner, not 'authenticated', so RPC writes pass).
  -- Direct end-user UPDATEs cannot touch these - they are the clout-fraud
  -- vectors (a broadcaster could otherwise set viewer_count = 1_000_000).
  IF is_end_user THEN
    IF NEW.viewer_count    IS DISTINCT FROM OLD.viewer_count    THEN
      RAISE EXCEPTION 'viewer_count is server-managed (use update_live_metrics RPC)'
        USING ERRCODE = '42501';
    END IF;
    IF NEW.peak_viewers    IS DISTINCT FROM OLD.peak_viewers    THEN
      RAISE EXCEPTION 'peak_viewers is server-managed (use update_live_metrics RPC)'
        USING ERRCODE = '42501';
    END IF;
    IF NEW.reaction_count  IS DISTINCT FROM OLD.reaction_count  THEN
      RAISE EXCEPTION 'reaction_count is server-managed'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  -- status, ended_at, started_at, livekit_room: ALLOWED from broadcaster.
  -- The RLS UPDATE policy already constrains these to broadcaster_id =
  -- auth.uid(), so a broadcaster can only mutate their own stream.

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_ca_settlement_transition_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  ord_old int; ord_new int;
BEGIN
  IF NEW.state = OLD.state THEN RETURN NEW; END IF;
  ord_old := array_position(ARRAY['open','locked_for_calculation','calculated',
              'validated','ledger_posted','post_commit_verified','final'], OLD.state);
  ord_new := array_position(ARRAY['open','locked_for_calculation','calculated',
              'validated','ledger_posted','post_commit_verified','final'], NEW.state);
  IF OLD.state = 'final' THEN
    RAISE EXCEPTION 'settlement % is final and cannot change state', OLD.id;
  END IF;
  IF NEW.state = 'failed' THEN
    NEW.updated_at := now(); RETURN NEW;
  END IF;
  IF OLD.state = 'failed' THEN  -- resume: re-enter anywhere at or before ledger_posted
    IF ord_new IS NULL OR ord_new > 5 THEN
      RAISE EXCEPTION 'failed settlement % may only resume at or before ledger_posted', OLD.id;
    END IF;
    NEW.updated_at := now(); RETURN NEW;
  END IF;
  IF ord_old IS NULL OR ord_new IS NULL OR ord_new <> ord_old + 1 THEN
    RAISE EXCEPTION 'invalid settlement transition % -> % for %', OLD.state, NEW.state, OLD.id;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.trg_ca_club_rake_daily_user_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_ids uuid[];
BEGIN
  SELECT array_agg(n.id) INTO v_ids
    FROM new_rows n
   WHERE n.club_id IS NOT NULL AND n.player_id IS NOT NULL AND n.rake_amount > 0;
  IF v_ids IS NOT NULL THEN
    PERFORM public.fn_ca_club_rake_daily_user_apply(v_ids);
  END IF;
  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  -- Never fail a raked hand for a reporting table.
  RAISE WARNING 'ca_club_rake_daily_user insert rollup failed: %', SQLERRM;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_ca_club_rake_daily_user_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r record;
BEGIN
  FOR r IN
    SELECT DISTINCT o.club_id, (o.created_at AT TIME ZONE 'UTC')::date AS day, o.player_id AS user_id
      FROM old_rows o WHERE o.club_id IS NOT NULL AND o.player_id IS NOT NULL
  LOOP
    PERFORM public.fn_ca_club_rake_daily_user_rebuild_day(r.club_id, r.day, r.user_id);
  END LOOP;
  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'ca_club_rake_daily_user delete rollup failed: %', SQLERRM;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_social_posts_video_contract_defaults()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_first_url text;
  v_yt_id text;
  v_provenance_yt_id text;
  v_prior_yt_id text;
  v_inferred_topic text;
  v_caller_role text := COALESCE(auth.role()::text, '');
  v_user_storage_video boolean := false;
BEGIN
  IF NEW.content_type IS DISTINCT FROM 'video' THEN
    RETURN NEW;
  END IF;

  v_first_url := NULLIF(NEW.media_urls ->> 0, '');
  v_yt_id := public.fn_extract_youtube_video_id(v_first_url);
  IF TG_OP = 'UPDATE' THEN
    v_prior_yt_id := COALESCE(
      public.fn_extract_youtube_video_id(NULLIF(OLD.media_urls ->> 0, '')),
      public.fn_extract_youtube_video_id(OLD.original_media_url),
      CASE
        WHEN OLD.youtube_video_id ~ '^[A-Za-z0-9_-]{11}$'
          THEN OLD.youtube_video_id
        ELSE NULL
      END
    );
  END IF;
  v_inferred_topic := public.fn_infer_video_topic(NEW.metadata, NEW.topics);

  IF v_inferred_topic <> 'unknown' THEN
    NEW.topic := v_inferred_topic;
  END IF;

  IF NEW.origin_type = 'user_upload' AND EXISTS (
    SELECT 1
    FROM public.profiles p
    WHERE p.id = NEW.author_id
      AND COALESCE(p.is_horse, false)
  ) THEN
    NEW.origin_type := 'horse';
  END IF;

  IF v_yt_id IS NOT NULL THEN
    PERFORM public.fn_queue_youtube_verification(
      v_yt_id,
      'social_post_write'
    );
    NEW.youtube_video_id := v_yt_id;
    NEW.canonical_asset_key := 'youtube:' || v_yt_id;
    NEW.playback_type := 'youtube_embed';
    IF COALESCE(auth.role()::text, '') <> 'service_role'
       OR NEW.rights_status NOT IN ('owned', 'licensed')
    THEN
      NEW.rights_status := 'embed_only';
    END IF;
  ELSIF public.fn_is_platform_public_storage_url(v_first_url)
  THEN
    NEW.playback_type := 'native';
    v_provenance_yt_id := COALESCE(
      public.fn_extract_youtube_video_id(NEW.original_media_url),
      CASE
        WHEN NEW.youtube_video_id ~ '^[A-Za-z0-9_-]{11}$'
          THEN NEW.youtube_video_id
        ELSE NULL
      END,
      v_prior_yt_id
    );
    -- A service worker may not publish a downloaded YouTube rendition by
    -- directly rewriting the post. The completion RPC first retires the exact
    -- claim, then exposes that completed job id as transaction-local proof for
    -- both the Reel and post updates.
    IF v_provenance_yt_id IS NOT NULL
       AND (
         TG_OP = 'INSERT'
         OR OLD.playback_type IS DISTINCT FROM 'native'
         OR NULLIF(OLD.media_urls ->> 0, '') IS DISTINCT FROM v_first_url
       )
       AND (
         v_caller_role <> 'service_role'
         OR NEW.rights_status NOT IN ('owned', 'licensed')
         OR NOT EXISTS (
           SELECT 1
           FROM public.video_transcode_jobs completion_job
           JOIN public.social_reels completion_reel
             ON completion_reel.id = completion_job.reel_id
           WHERE completion_job.id = current_setting(
                   'app.youtube_native_completion_job_id', true
                 )
             AND completion_job.status = 'completed'
             AND completion_job.reel_id = completion_reel.id
             AND completion_reel.source_post_id = NEW.id
             AND completion_job.user_id IS NOT DISTINCT FROM NEW.author_id
             AND completion_job.rights_status IS NOT DISTINCT FROM NEW.rights_status
             AND completion_job.canonical_asset_key = 'youtube:' || v_provenance_yt_id
             AND completion_job.output_url IS NOT DISTINCT FROM
               split_part(split_part(v_first_url, '?', 1), '#', 1)
         )
       )
    THEN
      RAISE EXCEPTION USING
        ERRCODE = '42501',
        MESSAGE = 'YouTube-derived native posts may only be published by complete_rights_cleared_youtube_transcode';
    END IF;
    -- A rights-cleared worker replaces only the playable URL. Retain the
    -- source identity so the native and embed representations deduplicate.
    IF v_caller_role = 'service_role'
       AND NEW.rights_status IN ('owned', 'licensed')
       AND v_provenance_yt_id IS NOT NULL
    THEN
      NEW.youtube_video_id := v_provenance_yt_id;
      NEW.canonical_asset_key := 'youtube:' || v_provenance_yt_id;
    ELSE
      NEW.youtube_video_id := NULL;
      NEW.canonical_asset_key := 'native:' || md5(v_first_url);
    END IF;
    v_user_storage_video := public.fn_is_user_video_storage_url(
      v_first_url,
      NEW.author_id
    );
    IF v_caller_role = 'authenticated'
       AND auth.uid() = NEW.author_id
       AND v_user_storage_video
    THEN
      NEW.rights_status := 'user_authorized';
    ELSIF v_caller_role = 'service_role'
       AND NEW.rights_status = 'user_authorized'
       AND v_user_storage_video
    THEN
      NEW.rights_status := 'user_authorized';
    ELSIF v_caller_role <> 'service_role'
       OR NEW.rights_status NOT IN ('owned', 'licensed')
    THEN
      NEW.rights_status := 'unknown';
    END IF;
  ELSIF NEW.playback_type = 'youtube_embed'
     OR NEW.youtube_video_id IS NOT NULL
  THEN
    v_provenance_yt_id := public.fn_extract_youtube_video_id(
      NEW.original_media_url
    );
    IF v_provenance_yt_id IS NOT NULL THEN
      NEW.media_urls := CASE
        WHEN jsonb_typeof(NEW.media_urls) = 'array'
          AND jsonb_array_length(NEW.media_urls) > 0
        THEN jsonb_set(
          NEW.media_urls,
          '{0}',
          to_jsonb(NEW.original_media_url),
          false
        )
        ELSE jsonb_build_array(NEW.original_media_url)
      END;
      NEW.youtube_video_id := v_provenance_yt_id;
      NEW.canonical_asset_key := 'youtube:' || v_provenance_yt_id;
      NEW.playback_type := 'youtube_embed';
      IF v_caller_role <> 'service_role'
         OR NEW.rights_status NOT IN ('owned', 'licensed')
      THEN
        NEW.rights_status := 'embed_only';
      END IF;
    ELSE
      NEW.youtube_video_id := NULL;
      NEW.canonical_asset_key := CASE
        WHEN v_first_url IS NOT NULL THEN 'external:' || md5(v_first_url)
        ELSE NULL
      END;
      NEW.playback_type := 'external_embed';
      NEW.rights_status := 'unknown';
    END IF;
  ELSE
    -- Caller-supplied playback/rights labels never turn an arbitrary URL into
    -- native media. Only the exact project Storage branch above can do that.
    NEW.youtube_video_id := NULL;
    NEW.canonical_asset_key := CASE
      WHEN v_first_url IS NOT NULL THEN 'external:' || md5(v_first_url)
      ELSE NULL
    END;
    NEW.playback_type := 'external_embed';
    NEW.rights_status := 'unknown';
  END IF;

  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.trgfn_award_social_post()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
    IF COALESCE(NEW.is_deleted,false) THEN RETURN NEW; END IF;
    IF length(btrim(COALESCE(NEW.content,''))) < 20 THEN RETURN NEW; END IF;
    PERFORM public.fn_social_reward_award(NEW.author_id,'social_post',
        'social_post_'||NEW.author_id::text||'_'||NEW.id::text, NEW.id::text);
    RETURN NEW;
EXCEPTION WHEN OTHERS THEN RETURN NEW; END $function$
